#!/usr/bin/env python3
"""MCP stdio server generated by api-tool-builder.  Dependencies: pyyaml only.

Implements the MCP wire protocol directly (JSON-RPC 2.0, newline-delimited over stdio) instead of importing an SDK, so it is
immune to SDK version churn and works in any harness that can launch a stdio MCP server (Claude Code, Cursor, Antigravity,
Gemini CLI, VS Code, Codex, Claude Desktop). Supported: initialize, ping, tools/list, tools/call.
Tools are registered dynamically from tools.spec.yaml; edit the spec and restart.
stdout is the protocol channel: all logging goes to stderr.
"""
import json
import sys
import threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from core import ApiTools, log

ROOT = Path(__file__).parent
tools = ApiTools(ROOT)
NAME = (tools.cfg.get("api") or {}).get("name", "apitool")
SUPPORTED = ("2024-11-05", "2025-03-26", "2025-06-18", "2025-11-25")
_out_lock = threading.Lock()


def send(msg):
    with _out_lock:
        sys.stdout.write(json.dumps(msg, default=str) + "\n")
        sys.stdout.flush()


def reply(rid, result=None, error=None):
    msg = {"jsonrpc": "2.0", "id": rid}
    if error is not None:
        msg["error"] = error
    else:
        msg["result"] = result
    send(msg)


def tool_list():
    out = []
    for e in tools.list_tools():
        out.append({"name": e["name"], "description": e["description"], "inputSchema": e["inputSchema"],
                    "annotations": {"title": e["name"].replace("_", " "), "readOnlyHint": e["readOnly"],
                                    "destructiveHint": e["destructive"], "openWorldHint": True}})
    return out


def handle_call(rid, params):
    name, args = params.get("name"), params.get("arguments") or {}
    log(f"call {name}")
    try:
        res = tools.call_tool(name, args)
    except Exception as e:  # core already guards; this is the last line of defence
        res = {"ok": False, "error": {"kind": "server", "message": f"{type(e).__name__}: {e}"}}
    reply(rid, {"content": [{"type": "text", "text": json.dumps(res, indent=2, default=str)}], "isError": not res.get("ok", False)})


def main():
    log(f"apitool MCP server '{NAME}' up: {len(tools.tools) + len(tools.composites)} tools, base_url={tools.base_url}")
    pool = ThreadPoolExecutor(max_workers=4)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            reply(None, error={"code": -32700, "message": "Parse error"})
            continue
        method, rid, params = msg.get("method"), msg.get("id"), msg.get("params") or {}
        if method is None:          # a response to something we never sent; ignore
            continue
        if rid is None:             # notification (e.g. notifications/initialized): no reply
            continue
        if method == "initialize":
            want = params.get("protocolVersion")
            reply(rid, {"protocolVersion": want if want in SUPPORTED or (isinstance(want, str) and want >= SUPPORTED[0]) else SUPPORTED[-1],
                        "capabilities": {"tools": {"listChanged": False}},
                        "serverInfo": {"name": NAME, "version": "1.0.0"}})
        elif method == "ping":
            reply(rid, {})
        elif method == "tools/list":
            reply(rid, {"tools": tool_list()})
        elif method == "tools/call":
            pool.submit(handle_call, rid, params)
        elif method in ("resources/list", "prompts/list"):
            reply(rid, {"resources" if method.startswith("res") else "prompts": []})
        else:
            reply(rid, error={"code": -32601, "message": f"Method not found: {method}"})
    pool.shutdown(wait=True)


if __name__ == "__main__":
    main()
